{"qas": [
  {"question": "According to the AGILE Index 2024, which two countries contributed over 300 models and datasets each to the Top 1000 influential Hugging Face AI resources, and what is their share of AI for SDGs literature?", "answer": "China and the United States each contributed over 300 models and datasets to Hugging Face's Top 1000, and together account for 34.7% and 23.2% of AI for SDGs literature, respectively.", "evidence": [{"page": 40, "quote": "Overall, China and the United States belong to the first tier in terms of contributions, contributing over 300 models and datasets each to the Top 1000 influential ones."}, {"page": 46, "quote": "Overall, the United States and China are in the first tier in terms of the number of AI for SDGs papers published, accounting for 34.7% and 23.2% of the AI for SDGs literature from all 14 countries, respectively."}]},
  {"question": "What are the four main working groups of the Global Partnership on AI (GPAI) established by Canada and France?", "answer": "Responsible AI, Data Governance, the Future of Work, and Innovation and Commercialization.", "evidence": [{"page": 34, "quote": "This organization, currently consisting of 28 member countries and the European Union, has set up four main working groups on Responsible AI, Data Governance, the Future of Work, and Innovation and Commercialization."}]},
  {"question": "What is the correlation coefficient between public awareness and trust in AI in BRICS countries, as reported in the AGILE Index 2024?", "answer": "The correlation coefficient is 0.84.", "evidence": [{"page": 36, "quote": "There is a strong positive correlation between public awareness and trust in AI, with a correlation coefficient of 0.84."}]},
  {"question": "Which country has the most balanced male-to-female participation in AI literature according to the AGILE Index 2024?", "answer": "China has the most balanced male-to-female participation in AI literature.", "evidence": [{"page": 37, "quote": "AGILE Index sees that China and Singapore have the lowest identified gender author ratios, at 1.2 and 2.0 respectively, ranking first and second."}]},
  {"question": "Which three SDGs are the most researched AI for SDGs topics among the 14 countries in the AGILE Index 2024?", "answer": "SDG3 (Good health and well-being), SDG9 (Industry, innovation and infrastructure), and SDG4 (Quality Education).", "evidence": [{"page": 47, "quote": "SDG3 (Good health and well-being), SDG9 (Industry, innovation and infrastructure) and SDG4 (Quality Education) be three of the most popular topics for all 14 countries."}]},
  {"question": "In the AGILE Index 2024, what is the indicator used to assess the number of AI-related risk cases/incidents in each country?", "answer": "D4.1. Number of AI-related risk cases/incidents & the GDP ratio.", "evidence": [{"page": 69, "quote": "Dimension 4 currently has one indicator:\n# ⚫ D4.1. Number of AI-related risk cases/incidents & the GDP ratio"}]}
]}
